// Deployment provenance is separated from the committed research manifest.
// - public/research-data/release_manifest.json: deterministic research manifest, committed, byte-comparable.
// - public/research-data/deployment_provenance.json: per-build identity (commit, CI run, build time, package hash),
//   gitignored, regenerated by every export/package build and deployed with the site and the research package.
// Consumers read the merged view via readReleaseManifest(); nothing else changes in their semantics.
import fs from "node:fs";
import path from "node:path";

export const PROVENANCE_FILE = "deployment_provenance.json";
export const LOCAL_PROVENANCE = { source_commit: "local-working-tree", build_context: "local", workflow_run_id: null };

export function buildProvenance(environment = process.env) {
  const ci = Boolean(environment.GITHUB_SHA || environment.RELEASE_COMMIT_SHA);
  return {
    schema_version: "atlas-deployment-provenance-v1",
    source_commit: environment.GITHUB_SHA ?? environment.RELEASE_COMMIT_SHA ?? LOCAL_PROVENANCE.source_commit,
    build_context: ci ? "github-actions" : LOCAL_PROVENANCE.build_context,
    workflow_run_id: environment.GITHUB_RUN_ID ?? null,
    generated_at: new Date().toISOString(),
    research_package: null,
    release_validation_package: null,
  };
}

export function readReleaseManifest(directory) {
  const manifestFile = path.join(directory, "release_manifest.json");
  if (!fs.existsSync(manifestFile)) return null;
  const manifest = JSON.parse(fs.readFileSync(manifestFile, "utf8"));
  const provenanceFile = path.join(directory, PROVENANCE_FILE);
  if (!fs.existsSync(provenanceFile)) return manifest;
  const provenance = JSON.parse(fs.readFileSync(provenanceFile, "utf8"));
  const merged = {
    ...manifest,
    source_commit: provenance.source_commit,
    build_context: provenance.build_context,
    workflow_run_id: provenance.workflow_run_id,
    generated_at: provenance.generated_at,
    research_package: provenance.research_package ?? manifest.research_package,
  };
  if (merged.release_validation && provenance.release_validation_package) merged.release_validation = { ...merged.release_validation, ...provenance.release_validation_package };
  return merged;
}
